# Glyph data: zlib-compressed 1-bit bitmaps, generated at build time
# from system DejaVu TTFs and compressed by the build agent.
# _BLOB = base64(zlib(all packed-1bit-row bytes, glyphs in font order,
# codes sorted)); _IDX = base64(zlib(per-glyph 6 bytes: code uint16 BE,
# advance, top, width, height)); empty glyphs (space) carry height 0
# and no blob bytes. FONTS is rebuilt below in the original format,
# so the renderer in main.py is unchanged.
import base64 as _b64
import struct as _st
import zlib as _zl
